struct VideoDec {
    char padding[0x100];
    int hid_endimage;
    int hid_vblank;
};
struct AudioDec {};
struct ReadBuf {};
struct VoBuf {};
struct StrFile {};

extern VideoDec videoDec;
extern AudioDec audioDec;
extern ReadBuf *readBuf;
extern VoBuf voBuf;
extern StrFile infile;
extern int videoDecTh;
extern int defaultTh;
extern void *voBufData;
extern void *voBufTag;
extern void *viBufTag;
extern void *mpegWork;
extern void *defStack;
extern void *audioBuff;
extern void *viBufData;
extern void *videoDecStack;
extern void *timeStamp;
extern void *_0_buf;
extern void (*nvlMPEGFreeFunc)(void *);

extern void endDisplay();
extern void audioDecReset(AudioDec *);
extern void readBufDelete(ReadBuf *);
extern void voBufDelete(VoBuf *);
extern int TerminateThread(int);
extern int DeleteThread(int);
extern int DisableDmac(int);
extern int RemoveDmacHandler(int, int);
extern int DisableIntc(int);
extern int RemoveIntcHandler(int, int);
extern void videoDecDelete(VideoDec *);
extern void audioDecDelete(AudioDec *);
extern void strFileClose(StrFile *);
extern "C" void free(void *);

#define DMAC_GIF 2
#define INTC_VBLANK_S 2

void nvlMPEGStop()
{
    endDisplay();
    audioDecReset( &audioDec );

    readBufDelete( readBuf );
    voBufDelete(&voBuf);

    TerminateThread(videoDecTh);
    DeleteThread(videoDecTh);

    TerminateThread(defaultTh);
    DeleteThread(defaultTh);

    DisableDmac(DMAC_GIF);
    RemoveDmacHandler(DMAC_GIF, videoDec.hid_endimage);

    DisableIntc(INTC_VBLANK_S);
    RemoveIntcHandler(INTC_VBLANK_S, videoDec.hid_vblank);

    videoDecDelete(&videoDec);
    audioDecDelete(&audioDec);

    strFileClose(&infile);

    if( nvlMPEGFreeFunc )
    {
        (*nvlMPEGFreeFunc)( voBufData );
        (*nvlMPEGFreeFunc)( voBufTag );
        (*nvlMPEGFreeFunc)( viBufTag );
        (*nvlMPEGFreeFunc)( mpegWork );
        (*nvlMPEGFreeFunc)( defStack );
        (*nvlMPEGFreeFunc)( audioBuff );
        (*nvlMPEGFreeFunc)( viBufData );
        (*nvlMPEGFreeFunc)( videoDecStack );
        (*nvlMPEGFreeFunc)( timeStamp );
        (*nvlMPEGFreeFunc)( _0_buf );
        (*nvlMPEGFreeFunc)( readBuf );
    }
    else
    {
        free( voBufData );
        free( voBufTag );
        free( viBufTag );
        free( mpegWork );
        free( defStack );
        free( audioBuff );
        free( viBufData );
        free( videoDecStack );
        free( timeStamp );
        free( _0_buf );
        free( readBuf );
    }
}
